record.field:
Remote = self.remote_id
DeviceModel = env['mdm.measurement.device']
SensorModel = env['mdm.measurement.device.sensor']
today_str = fields.Date.today()

device_condition = [
    ('remotecontrol_id', '=', Remote.id),
    ('remotecontrol_params', '!=', False),
]
if selected_device_ids:
    device_condition.append(('id', 'in', selected_device_ids))
devices = DeviceModel.search(device_condition)

sensors = SensorModel.search([
    ('device_id', 'in', devices.ids),
    ('remotecontrol_params', '!=', False),
])
# Optimize: build map of sensor_id -> most recent reading (single query)
last_readings_map = {}
if sensors:
    sensor_ids = [s.id for s in sensors]
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for row in cr.fetchall():
        last_readings_map[row[0]] = row[1]

sensors_by_device = {}
for sensor in sensors:
    sensors_by_device.setdefault(sensor.device_id.id, []).append(sensor)

plan = []
for device in devices:
    try:
        device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
    except Exception:
        device_cfg = {}
    sdb_name = (device_cfg.get('sdb_name') or '').strip()
    if not sdb_name:
        continue
    device_sensors = sensors_by_device.get(device.id) or []
    if not device_sensors:
        continue
    sensor_list = []
    from_dates = []
    for sensor in device_sensors:
        try:
            sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
        except Exception:
            sensor_cfg = {}
        column = (sensor_cfg.get('column') or '').strip()
        if not column:
            continue
        last_reading_time = last_readings_map.get(sensor.id)
        if last_reading_time:
            sensor_from_date = str(last_reading_time)[:19]
        else:
            start_cfg = sensor_cfg.get('start_date') or device_cfg.get('start_date')
            if start_cfg:
                sensor_from_date = start_cfg
            else:
                year_str = today_str[:4]
                sensor_from_date = '%s-01-01' % year_str
        sensor_list.append({
            'sensor_id': sensor.id,
            'column': column,
        })
        from_dates.append(sensor_from_date)
    if not sensor_list:
        continue
    plan.append({
        'device_id': device.id,
        'sdb_name': sdb_name,
        'from_date': min(from_dates),
        'sensors': sensor_list,
    })
bag['devices_plan'] = plan
bag['devices_plan_count'] = len(plan)
